import * as React from "react";
import { cx } from "./cx";

export interface SkeletonProps extends React.HTMLAttributes<HTMLSpanElement> {
  width?: number | string;
  height?: number | string;
}

export function Skeleton({ width, height = 14, style, className, ...props }: SkeletonProps) {
  return (
    <span
      aria-hidden="true"
      className={cx("rs-skeleton", className)}
      style={{ width, height, ...style }}
      {...props}
    />
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Skeleton: a quiet pulse; still under reduced motion ── */
.rs-skeleton{display:block;background:var(--divider-subtle);border-radius:var(--radius-sm);animation:rsSkel 1.6s ease-in-out infinite}
@keyframes rsSkel{0%,100%{opacity:1}50%{opacity:.55}}
@media(prefers-reduced-motion:reduce){.rs-skeleton{animation:none}}
